When using with `useGeographic()`, `setGeometry()` misplaces the feature.

This PR fixes the issue by applying `userProjection` on `CHANGEFEATURE` event too.

Reproduction:
```js
import { Point } from 'ol/geom';
import { Feature, Map, View } from 'ol';
import TileLayer from 'ol/layer/Tile';
import { useGeographic } from 'ol/proj';
import OSM from 'ol/source/OSM';
import WebGLVectorLayer from 'ol/layer/WebGLVector';
import VectorSource from 'ol/source/Vector';
import './style.css';

useGeographic();

const f = new Feature(new Point([135, 35]));

setTimeout(() => {
  f.setGeometry(new Point([135, 35]));
  // or, f.changed();
}, 1000);

new Map({
  target: 'map',
  layers: [
    new TileLayer({
      source: new OSM()
    }),
    new WebGLVectorLayer({
      style: {
        'circle-radius': 8,
        'circle-stroke-color': 'red',
        'circle-stroke-width': 2,
      },
      source: new VectorSource({
        features: [f],
      })
    }),
  ],
  view: new View({
    center: [0, 0],
    zoom: 2
  })
});
```

